cat > /tmp/setup_alpine2.exp << 'EXPECT'
#!/usr/bin/expect -f

set timeout 120

# Start QEMU in a subshell
spawn -open [open "| qemu-system-x86_64 -name alpine -m 2048 -smp 2 -drive file=/app/alpine-disk.qcow2,if=virtio -cdrom /app/alpine.iso -netdev user,id=n1,hostfwd=tcp::2222-:22 -device virtio-net,netdev=n1 -serial unix:/tmp/serial.sock,server,nowait -nographic" "r+"]

# Wait for boot
expect {
    "boot:" {
        send "\r"
        exp_continue
    }
    timeout {
        puts "Timeout waiting for boot"
        exit 1
    }
}

# Wait for login prompt
expect {
    "login:" {
        send "root\r"
    }
    timeout {
        puts "Timeout waiting for login"
        exit 1
    }
}

# Wait for root prompt
expect {
    "# " {
        send "setup-alpine\r"
    }
    timeout {
        puts "Timeout waiting for prompt"
        exit 1
    }
}

# Configure hostname
expect {
    "Hostname" {
        send "\r"
    }
    timeout {
        puts "Timeout after hostname prompt"
        exit 1
    }
}

# Configure interface
expect {
    "Interface" {
        send "eth0\r"
    }
    timeout {
        puts "Timeout after interface prompt"
        exit 1
    }
}

